registration_steps.body:
RegistrationStep(
  data: const {'id': 'merchants.shop_setup'},
  content: Builder(
    builder: (context) => ShopSetupSlide(
      capture: MerchantsShopSetupAdapter(),
      initialPhone: RegistrationStepScope.of(context).account?.phone,
      onContinue: () => RegistrationStepScope.of(context).next(),
    ),
  ),
)

boot_hooks.body:
if (!kIsWeb && (defaultTargetPlatform == TargetPlatform.android || defaultTargetPlatform == TargetPlatform.iOS || defaultTargetPlatform == TargetPlatform.macOS)) {
  try {
    if (Firebase.apps.isEmpty) {
      await Firebase.initializeApp();
    }
    FirebaseMessaging.onBackgroundMessage(firebaseMessagingBackgroundHandler);
  } catch (e) {
    debugPrint('Firebase boot skipped: $e');
  }
}

if (!kIsWeb && defaultTargetPlatform == TargetPlatform.windows) {
  WidgetsBinding.instance.addPostFrameCallback((_) {
    try {
      DesktopNotificationPoller.instance.start();
    } catch (e) {
      debugPrint('Desktop notification poller boot skipped: $e');
    }
  });
}

